187	        Yii::$app->db->createCommand(
188	            "UPDATE max_win_user_bonus SET left_until_max_amount = left_until_max_amount - :amount where id = :id;"
189	        )->bindValues([':amount' => $amount, ':id' => $this->id])->execute();
