100	                    'userId' => $user ? $user->id : null,
101	                    'gameId' => $game->id,
102	                    'data' => $game_action,
103	                ]),'__TEST__GR_CALLBACK');
104	        }
105	
106	        if($game_action['type'] === 'freespin'){
107	            if (!isset($game_action['freespin_id'])){
108	                Logger::writeInfo('processingGameTransaction freespin_id empty: SessionId:'.$game_action['session_id']);
109	                return false;
110	            }
111	
112	            /** @var Freespin $freespin */
113	            $freespin = Freespin::find()->where(['freespin_id' => $game_action['freespin_id']])->one();
114	            if (!$freespin) {
115	                Logger::writeInfo('processingGameTransaction Freespin not found: SessionId:'.$game_action['session_id']);
116	                return false;
117	            }
118	            /** @var UserBonus $userBonus */
119	            $userBonus = $freespin->userBonus;
120	
121	            if (!$userBonus) {
122	                if ($freespin->hasMaxWin()) {
123	                    self::updateMaxWin($freespin);
