167	                        $userBonus->amount_wager = $userBonus->amount_wager + $wagerSum;
168	                    }
169	                    $userBonus->amount = $userBonus->amount + $addAmount;
170	
171	                }
172	
173	                if ($userBonus->hasMaxWin()) {
174	                    self::updateMaxWin($userBonus);
175	                    if (!$userBonus->is_wager && !$freespin->isEnded()) {
176	                        $transaction = Yii::$app->db->beginTransaction();
177	                        $wallet = Wallet::find()->where(['user_id'=>$user->id,'currency'=>$game_action['currency']])->one();
