181	                            $amount = $userBonus->maxWinUserBonus->getAllowedAmountToDep($amount);
182	                            if (!YII_ENV_PROD) Logger::writeInfo("__TEST__GR_CALLBACK [" . __LINE__ . "]:" . json_encode(['amount' => $amount]));
183	                            $wallet->deposit($amount);
