185	                        } catch (Exception $ex) {
186	                            $transaction->rollBack();
187	                            Logger::writeError('Bonus confirm error: user_bonusId:'.$userBonus->id .' userId:'.$userBonus->user_id .' CAUSE: '.$ex->getMessage());
188	                            throw $ex;
189	                        }
190	                    }
191	                }
192	            }
193	
194	            // @infection-ignore-all блок прежний и в common/unit без БД не исполняется; новое решение в нём — FreespinEndCredit::isDue (unit-тесты)
195	            if($freespin->isEnded($game_action['time'])){
196	                if ($userBonus->is_wager && $freespin->total_win > 0) {
197	                    Notice::sendNotice($user->id, Notice::LOGIC_FS_WAGER_ACTIVE,
198	                        ['amount' => $freespin->total_win, 'wager_amount' => $userBonus->wager]);
199	                }
200	                if(!$userBonus->is_wager){
201	                    // сумма, зачисленная при активации (accrual_time), второй раз не зачисляется (DBR-009, DBR-011)
202	                    if(FreespinEndCredit::isDue($userBonus->amount, $userBonus->accrual_time)){
203	                        $transaction = Yii::$app->db->beginTransaction();
204	                        $wallet = Wallet::find()->where(['user_id'=>$user->id,'currency'=>$userBonus->currency])->one();
205	                        try {
206	                            $wallet->deposit($userBonus->getRealAmount());
207	                            $userBonus->accrual_time = time();
208	                            $userBonus->status = UserBonus::STATUS_END;
209	                            $userBonus->save();
210	                            $transaction->commit();
211	                        } catch (Exception $ex) {
212	                            $transaction->rollBack();
213	                            Logger::writeError('Bonus confirm error: user_bonusId:'.$userBonus->id .' userId:'.$userBonus->user_id .' CAUSE: '.$ex->getMessage());
214	                            throw $ex;
215	                        }
216	                    }else{
217	                        $userBonus->closeBonus();
218	                    }
219	                } elseif ($userBonus->checkForUpdateWager($game_action['time']) && $userBonus->wager <= 0) {
220	                    //якщо вейджер 0 - закриваємо бонус
221	                    $userBonus->save(false);
222	                    $userBonus->closeWagerBonus();
223	                }
224	            }
225	
226	            $userBonus->save(false);
227	
228	        }
229	        elseif ($game_action['action'] === 'bet')
230	        {
231	
232	
233	            if (!YII_ENV_PROD) {
234	                $tmp = $userBonus = UserBonus::find()->where(['user_id'=>$user->id,'status'=>UserBonus::STATUS_ACTIVE,'is_wager'=>true,'currency'=>$game_action['currency']])
235	                    ->andWhere(['>=','wager', 0])
236	                    ->andWhere('amount_wager IS NOT NULL')
