238	                    ->orderBy('id DESC')->one();
239	                Logger::writeInfo('__TEST__GR_CALLBACK: [' . __LINE__ . '] ' . json_encode($tmp));
240	                unset($tmp);
241	            }
242	            if ($userBonus = UserBonus::find()->where(['user_id'=>$user->id,'status'=>UserBonus::STATUS_ACTIVE,'is_wager'=>true,'currency'=>$game_action['currency']])
243	                ->andWhere(['>=','wager', 0])
244	                ->andWhere('amount_wager IS NOT NULL')
245	                ->andWhere(['>', 'amount_wager', 0.00])
246	                ->orderBy('id DESC')->one()) {
247	
248	                if (!YII_ENV_PROD) Logger::writeInfo('__TEST__GR_CALLBACK: [' . __LINE__ . '] ' . json_encode([
249	                        'time' => $game_action['time'],
250	                        'checkForUpdateWager' => $userBonus->checkForUpdateWager($game_action['time']),
251	                        'considerWager' => $game->considerWager(),
252	                    ]));
253	                if ($userBonus->checkForUpdateWager($game_action['time']) && !$game->considerWager()) {
254	                    //если игра в групе не считать вейджер, то пропускаем
