742	    public function cancelFreespin(int $status = self::STATUS_CANCEL_ADMIN): bool
743	    {
744	        if (!in_array($this->status, [self::STATUS_READY, self::STATUS_USED])) {
745	            $this->addError(attribute: 'status',error: 'Forbidden cancel if status ready');
746	            return false;
747	        }
748	
749	        // Провайдер-агностичне скасування. Адаптер логує деталі; тут піднімаємо
750	        // помилку, щоб адмінка (actionCancel) показала причину.
751	        if (!self::cancelByProvider($this)) {
752	            $this->addError('status', 'Provider rejected freespin cancel');
753	            return false;
754	        }
755	
756	        $this->status = $status;
757	        $this->is_canceled = time();
758	        if (!$this->save()) {
759	            return false;
760	        }
761	        if ($this->userBonus) {
762	            $this->userBonus->closeBonus();
763	        } else {
764	            $this->bonusCodLog?->closeBonus();
765	        }
