        if ($wagerUserBonus) {
            if ($wagerUserBonus->freespin_id) {
                $freespinOld = Freespin::find()->where(['freespin_id' => $wagerUserBonus->freespin_id])->one();
                if ($freespinOld && $freespinOld->valid_until > time()) {
                    if ($freespinOld->status == Freespin::STATUS_READY) {
                        $freespinOldToCancel = $freespinOld;
                    } elseif ($freespinOld->status == Freespin::STATUS_USED) {
                        $transaction->rollBack();
