                            $freespin->status = Freespin::STATUS_CANCEL_AUTO;
                            $freespin->is_canceled = time();
                            $freespin->save();
                        }
                        $html = $this->renderAjax('_popup-error', ['text' => Yii::t('app', 'cannot_cancel_fs_after_start')]);
                        return ['success' => false, 'html' => $html];
                    }
                }
            }
            $wagerUserBonus->refuseBonus();
            $wagerUserBonusTitle = $wagerUserBonus->is_promocod
