                $user->setSystemMessage(Yii::t('app', 'you_canceled_wager_bonus'), $text);
            }
        }
    }
    $userBonus->accepted_time = time();
    $userBonus->status = UserBonus::STATUS_ACTIVE;
    $userBonus->save(false);
    $transaction->commit();
} catch (Exception $ex) {
    $transaction->rollBack();
    Logger::writeError('Bonus confirm error: user_bonusId:' . $userBonus->id . ' userId:' . $userBonus->user_id . ' CAUSE: ' . $ex->getMessage());
    throw $ex;
}

