    $split = EgtWallet::giftSpinSplit($creditRealSync, $rawAmountCoins);

    if ($creditRealSync && $amount > 0) {
        Yii::$app->db->createCommand(
            'UPDATE wallet SET amount = amount + :amount WHERE id = :id',
