    $this->debugLog($result['new'] ? 'win_ok' : 'win_isset_tr');

    return Protocol::success($result['balance'], $this->gameAction['transaction_id']);
}

/**
 * Фриспін-виграш, який не йде на реальний баланс (вейджер або max win): транзакцію записано,
 * гроші зарахує черга. Повертає «віртуальний» баланс для відповіді провайдеру або null,
 * якщо виграш треба зарахувати звичайним шляхом.
 */
private function applyFreespinWin(float $balanceBefore): ?float
{
    /** @var Freespin|null $freespin */
    $freespin = Freespin::find()->where(['freespin_id' => $this->gameAction['freespin_id']])->one();
    if (!$freespin) {
        return null;
    }

    $amount = $this->gameAction['amount'];
    FreespinProgressService::recordSpinProgress($freespin, $this->postedQuantity(), $amount);
    $this->gameAction['time'] = time();

    $userBonus = $freespin->userBonus;

    // По ТЗ: вейджерний ФС-бонус — вейджер нараховується в черзі від виграшу, реальний баланс не змінюється
    if ($userBonus && $userBonus->is_wager) {
        $this->gameAction['balance_after'] = $balanceBefore;
        GameTransaction::saveNewGameTransaction($this->gameAction);

        return $balanceBefore + $amount;
    }

    if ($userBonus && $userBonus->hasMaxWin()) {
        [$credited, $userBonus->maxWinLeftUntilMaxAmount] = Protocol::capByMaxWin($amount, (float)$userBonus->maxWinLeftUntilMaxAmount);

        return $this->saveVirtualWin($balanceBefore + $credited);
    }

    $userBonusCod = $freespin->userBonusCod;
    if ($userBonusCod && in_array($freespin->quantity_left, ['0', 0], true)) {
        $userBonusCod->closeBonus();
    }

    if (!$userBonus && $freespin->hasMaxWin()) {
        [$credited, $freespin->maxWinLeftUntilMaxAmount] = Protocol::capByMaxWin($amount, (float)$freespin->maxWinLeftUntilMaxAmount);

        return $this->saveVirtualWin($balanceBefore + $credited);
    }

    return null;
}

private function saveVirtualWin(float $virtualBalance): float
{
    $this->gameAction['balance_after'] = $virtualBalance;
    GameTransaction::saveNewGameTransaction($this->gameAction);

    return $virtualBalance;
}

